import { z } from 'zod';
import { defineOption } from '../../lib/define-option.js';
import { commaSeparated } from '../../parsers.js';

export const OAUTH_CONSUMER_RIGHTS = [
  'almighty',
  'access_organisations',
  'access_organisations_bills',
  'access_organisations_credit_count',
  'access_organisations_consumption_statistics',
  'access_personal_information',
  'manage_organisations',
  'manage_organisations_services',
  'manage_organisations_applications',
  'manage_organisations_members',
  'manage_personal_information',
  'manage_ssh_keys',
];

export const consumerDescriptionOption = defineOption({
  name: 'description',
  schema: z.string().optional(),
  description: 'Description of the OAuth consumer',
  placeholder: 'description',
});

export const consumerUrlOption = defineOption({
  name: 'url',
  schema: z.string().optional(),
  description: 'Home page URL of the application using the OAuth consumer',
  placeholder: 'url',
});

export const consumerBaseUrlOption = defineOption({
  name: 'base-url',
  schema: z.string().optional(),
  description: 'Base URL of the application, used for OAuth callbacks',
  placeholder: 'base-url',
});

export const consumerPictureOption = defineOption({
  name: 'picture',
  schema: z.string().optional(),
  description: 'URL of the picture of the OAuth consumer',
  placeholder: 'picture',
});

export const consumerRightsOption = defineOption({
  name: 'rights',
  schema: z
    .string()
    .transform(commaSeparated)
    .pipe(z.array(z.enum(OAUTH_CONSUMER_RIGHTS)))
    .optional(),
  description: `Comma-separated rights granted to the OAuth consumer (${OAUTH_CONSUMER_RIGHTS.join(', ')})`,
  placeholder: 'rights',
});

/**
 * Build the API body from the options, ignoring those not set.
 * @param {{ name?: string, description?: string, url?: string, baseUrl?: string, picture?: string, rights?: string[] }} fields
 */
export function toConsumerBody({ name, description, url, baseUrl, picture, rights }) {
  const body = { name, description, url, baseUrl, picture };
  if (rights != null) {
    body.rights = Object.fromEntries(OAUTH_CONSUMER_RIGHTS.map((right) => [right, rights.includes(right)]));
  }
  return Object.fromEntries(Object.entries(body).filter(([, value]) => value != null));
}

/**
 * @param {Record<string, boolean>} rights
 */
export function grantedRights(rights) {
  return Object.entries(rights ?? {})
    .filter(([, granted]) => granted)
    .map(([right]) => right);
}
