import { consumerKeyArg } from './oauth-consumers.args.js';
import { grantedRights } from './oauth-consumers.options.js';

export const oauthConsumersGetCommand = defineCommand({
  description: 'Get information about an OAuth consumer',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    withSecret: defineOption({
      name: 'with-secret',
      schema: z.boolean().default(false),
      description: 'Also display the secret of the OAuth consumer',
    }),
    format: humanJsonOutputFormatOption,
  },
  args: [consumerKeyArg],
  async handler(options, key) {
    const { org: orgaIdOrName, withSecret, format } = options;

    const id = await Organisation.getId(orgaIdOrName);
    const consumer = await get({ id, key }).then(sendToApi);
    if (withSecret) {
      const { secret } = await getSecret({ id, key }).then(sendToApi);
      consumer.secret = secret;
    }

    if (format === 'json') {
      Logger.printJson(consumer);
      return;
