import { create } from '@clevercloud/client/esm/api/v2/oauth-consumer.js';
import { z } from 'zod';
import { defineArgument } from '../../lib/define-argument.js';
import { defineCommand } from '../../lib/define-command.js';
import { Logger } from '../../logger.js';
import * as Organisation from '../../models/organisation.js';
import { sendToApi } from '../../models/send-to-api.js';
import { humanJsonOutputFormatOption, orgaIdOrNameOption } from '../global.options.js';
import {
  consumerBaseUrlOption,
  consumerDescriptionOption,
  consumerPictureOption,
  consumerRightsOption,
  consumerUrlOption,
  toConsumerBody,
} from './oauth-consumers.options.js';

export const oauthConsumersCreateCommand = defineCommand({
  description: 'Create an OAuth consumer',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    description: consumerDescriptionOption,
    url: consumerUrlOption,
    baseUrl: consumerBaseUrlOption,
    picture: consumerPictureOption,
    rights: consumerRightsOption,
    format: humanJsonOutputFormatOption,
  },
  args: [
    defineArgument({
      schema: z.string(),
      description: 'Name of the OAuth consumer',
      placeholder: 'name',
    }),
  ],
  async handler(options, name) {
    const { org: orgaIdOrName, format, ...fields } = options;

    if (fields.baseUrl == null) {
      throw new Error('The --base-url option is required to create an OAuth consumer');
    }

    const id = await Organisation.getId(orgaIdOrName);
    const body = toConsumerBody({ description: name, ...fields, name });
    const consumer = await create({ id }, body).then(sendToApi);

    if (format === 'json') {
      Logger.printJson(consumer);
    } else {
      Logger.printSuccess(`OAuth consumer ${name} created successfully (key: ${consumer.key})`);
    }
  },
});
