import { get, update } from '@clevercloud/client/esm/api/v2/oauth-consumer.js';
import { defineCommand } from '../../lib/define-command.js';
import { Logger } from '../../logger.js';
import * as Organisation from '../../models/organisation.js';
import { sendToApi } from '../../models/send-to-api.js';
import { humanJsonOutputFormatOption, orgaIdOrNameOption } from '../global.options.js';
import { consumerKeyArg } from './oauth-consumers.args.js';
import {
  consumerBaseUrlOption,
  consumerDescriptionOption,
  consumerPictureOption,
  consumerRightsOption,
  consumerUrlOption,
  grantedRights,
  toConsumerBody,
} from './oauth-consumers.options.js';
import { defineOption } from '../../lib/define-option.js';
import { z } from 'zod';

export const oauthConsumersUpdateCommand = defineCommand({
  description: 'Update an OAuth consumer',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    name: defineOption({
      name: 'name',
      schema: z.string().optional(),
      description: 'New name of the OAuth consumer',
      placeholder: 'name',
    }),
    description: consumerDescriptionOption,
    url: consumerUrlOption,
    baseUrl: consumerBaseUrlOption,
    picture: consumerPictureOption,
    rights: consumerRightsOption,
    format: humanJsonOutputFormatOption,
  },
  args: [consumerKeyArg],
  async handler(options, key) {
    const { org: orgaIdOrName, format, ...fields } = options;

    const id = await Organisation.getId(orgaIdOrName);
    const current = await get({ id, key }).then(sendToApi);

    // The API replaces the whole consumer, so start from the current one
    const body = {
      ...toConsumerBody({ ...current, rights: grantedRights(current.rights) }),
      ...toConsumerBody(fields),
    };
    const consumer = await update({ id, key }, body).then(sendToApi);

    if (format === 'json') {
      Logger.printJson(consumer);
    } else {
      Logger.printSuccess(`OAuth consumer ${key} updated successfully`);
    }
  },
});
