import { remove } from '@clevercloud/client/esm/api/v2/oauth-consumer.js';
import { defineCommand } from '../../lib/define-command.js';
import { confirm } from '../../lib/prompts.js';
import { Logger } from '../../logger.js';
import * as Organisation from '../../models/organisation.js';
import { sendToApi } from '../../models/send-to-api.js';
import { orgaIdOrNameOption, skipConfirmationOption } from '../global.options.js';
import { consumerKeyArg } from './oauth-consumers.args.js';

export const oauthConsumersDeleteCommand = defineCommand({
  description: 'Delete an OAuth consumer',
  since: null,
  options: {
    org: orgaIdOrNameOption,
    yes: skipConfirmationOption,
  },
  args: [consumerKeyArg],
  async handler(options, key) {
    const { org: orgaIdOrName, yes: skipConfirmation } = options;

    if (!skipConfirmation) {
      await confirm(`Delete the OAuth consumer ${key}?`, 'OAuth consumer not deleted');
    }

    const id = await Organisation.getId(orgaIdOrName);
    await remove({ id, key }).then(sendToApi);

    Logger.printSuccess(`OAuth consumer ${key} deleted successfully`);
  },
});
